DO $spell_pilot$
DECLARE
  expected jsonb;
  actual jsonb;
BEGIN
  LOCK TABLE spell_data IN SHARE ROW EXCLUSIVE MODE;
  IF NOT EXISTS (SELECT 1 FROM spell_data WHERE "referenceKey" IN ('acid_splash', 'fire_bolt', 'ray_of_frost', 'sacred_flame', 'vicious_mockery', 'burning_hands', 'thunderwave', 'fireball', 'lightning_bolt', 'ice_storm', 'flame_strike', 'cure_wounds', 'healing_word', 'eldritch_blast', 'scorching_ray', 'magic_missile', 'hunger_of_hadar', 'chromatic_orb', 'hold_person', 'unseen_servant')) THEN
    RAISE NOTICE 'Spell pilot data backfill skipped: no canonical pilot rows in this fixture catalog.';
    RETURN;
  END IF;
  FOR expected IN SELECT value FROM jsonb_array_elements($baseline$[{"id": 1, "name": "Брызги кислоты", "description": "Вы кидаете кислотный шарик. Выберите одно существо, которое вы видите в пределах дистанции, или два существа, которых вы видите в пределах дистанции, находящихся в пределах 5 футов друг от друга. Цель должна преуспеть в спасброске Ловкости, иначе получит 1к6 урона кислотой.\\nУрон этого заклинания увеличивается на 1к6, когда вы достигаете 5-го уровня (2к6), 11-го уровня (3к6) и 17-го уровня (4к6).", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T17:22:16.90104", "updatedAt": "2026-05-16T22:41:52.482355", "level": 0, "castingTime": "Действие", "range": "60 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": null, "requiresSavingThrow": false, "requiresAttackRoll": false, "damageDice": "1d6", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "conjuration", "savingThrowAbility": null, "attackType": "none", "damageType": "acid", "targetType": "multipleCreatures", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "acid_splash", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": []}, {"id": 13, "name": "Огненный снаряд", "description": "Вы кидаете сгусток огня в существо или предмет в пределах дистанции. Совершите по цели дальнобойную атаку заклинанием. При попадании цель получает урон огнём 1к10. Горючие предметы, по которым попало это заклинание, воспламеняются, если их никто не несет и не носит.\\nУрон этого заклинания увеличивается на 1к10, когда вы достигаете 5-го уровня (2к10), 11-го уровня (3к10), 17-го уровня (4к10).", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T17:22:16.90104", "updatedAt": "2026-05-16T22:41:52.482355", "level": 0, "castingTime": "Действие", "range": "120 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": null, "requiresSavingThrow": false, "requiresAttackRoll": true, "damageDice": "1d10", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": "rangedSpell", "damageType": "fire", "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "fire_bolt", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": []}, {"id": 9, "name": "Луч холода", "description": "Холодный сине-белый луч устремляется к существу, находящемуся в пределах дистанции. Совершите по цели дальнобойную атаку заклинанием. При попадании она получает урон холодом 1к8, а скорость до начала вашего следующего хода уменьшается на 10 футов.\\nУрон от заклинания увеличивается на 1к8, когда вы достигаете 5-го уровня (2к8), 11-го уровня (3к8) и 17-го уровня (4к8).", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T17:22:16.90104", "updatedAt": "2026-05-16T22:41:52.482355", "level": 0, "castingTime": "Действие", "range": "60 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": null, "requiresSavingThrow": false, "requiresAttackRoll": true, "damageDice": "1d8", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": "rangedSpell", "damageType": "cold", "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "ray_of_frost", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": []}, {"id": 17, "name": "Священное пламя", "description": "На существо, которое вы видите в пределах дистанции, нисходит сияние, похожее на огонь. Цель должна преуспеть в спасброске Ловкости, иначе получит 1к8 урона излучением. Для этого спасброска цель не получает преимуществ от укрытия.\\nУрон этого заклинания увеличивается на 1к8, когда вы достигаете 5-го уровня (2к8), 11-го уровня (3к8) и 17-го уровня (4к8).", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T17:22:16.90104", "updatedAt": "2026-05-16T22:41:52.482355", "level": 0, "castingTime": "Действие", "range": "60 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": null, "requiresSavingThrow": true, "requiresAttackRoll": false, "damageDice": "1d8", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": "dexterity", "attackType": "none", "damageType": "radiant", "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "sacred_flame", "damageParts": null, "shortDescription": null, "availableForClassIds": [3], "availableForSubclassIds": []}, {"id": 6, "name": "Злая насмешка", "description": "Вы испускаете на существо, видимое в пределах дистанции, поток оскорблений вперемешку с тонкой магией. Если цель слышит вас (при этом она не обязана вас понимать), она должна преуспеть в спасброске Мудрости, иначе получит урон психической энергией 1к4, и следующий бросок атаки до конца своего следующего хода совершит с помехой.\\nУрон этого заклинания увеличивается на 1к4, когда вы достигаете 5-го уровня (2к4), 11-го уровня (3к4) и 17-го уровня (4к4).", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T17:22:16.90104", "updatedAt": "2026-05-16T22:41:52.482355", "level": 0, "castingTime": "Действие", "range": "60 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": null, "requiresSavingThrow": true, "requiresAttackRoll": false, "damageDice": "1d4", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": false, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "enchantment", "savingThrowAbility": "wisdom", "attackType": "none", "damageType": "psychic", "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "vicious_mockery", "damageParts": null, "shortDescription": null, "availableForClassIds": [2], "availableForSubclassIds": []}, {"id": 59, "name": "Огненные ладони", "description": "Соединив ладони и растопырив пальцы веером, вы испускаете из них тонкие языки пламени. Все существа в пределах 15-футового конуса должны совершить спасбросок Ловкости. Существо получает 3к6 урона огнём при провале и половину этого урона при успехе.\\nПламя поджигает все горючие предметы, которые никто не несёт и не носит.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T22:37:10.895311", "updatedAt": "2026-05-16T22:41:52.482355", "level": 1, "castingTime": "Действие", "range": "На себя (15-футовый конус)", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 2-го уровня или выше, урон увеличивается на 1к6 за каждый уровень ячейки выше первого.", "requiresSavingThrow": true, "requiresAttackRoll": false, "damageDice": "3d6", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": false, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": 15, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": "dexterity", "attackType": "none", "damageType": "fire", "targetType": "area", "areaOfEffectType": "cone", "durationType": "instantaneous", "referenceKey": "burning_hands", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": [26, 30]}, {"id": 34, "name": "Волна грома", "description": "От вас исходит волна громовой силы. Все существа в кубе с длиной ребра 15 футов, исходящего от вас, должны совершить спасбросок Телосложения. При провале существо получает 2к8 урона звуком и отталкивается на 10 футов от вас. При успехе существо получает половину урона и не толкается.\\nКроме того, незакреплённые предметы, оказавшиеся полностью в области эффекта, автоматически толкаются на 10 футов от вас эффектом заклинания, и заклинание издает громовой рокот, слышимый на расстоянии 300 футов.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T21:48:35.40584", "updatedAt": "2026-05-16T22:41:52.482355", "level": 1, "castingTime": "Действие", "range": "На себя (15-футовый куб)", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 2-го уровня или выше, урон увеличивается на 1к8 за каждый уровень ячейки выше первого.", "requiresSavingThrow": true, "requiresAttackRoll": false, "damageDice": "2d8", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": 15, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": "constitution", "attackType": "none", "damageType": "thunder", "targetType": "area", "areaOfEffectType": "cube", "durationType": "instantaneous", "referenceKey": "thunderwave", "damageParts": null, "shortDescription": null, "availableForClassIds": [2, 4, 10, 12], "availableForSubclassIds": [30]}, {"id": 393, "name": "Огненный шар", "description": "Яркий луч вылетает из вашего указательного пальца в точку, выбранную вами в пределах дистанции, где и происходит взрыв пламени с гулким ревом. Все существа в пределах сферы с радиусом 20 футов с центром в этой точке должны совершить спасбросок Ловкости. Цель получает 8к6 урона огнём при провале или половину этого урона при успехе. Этот огонь огибает углы. Он воспламеняет горючие предметы, которые никто не несет и не носит.", "source": "PHB 2014", "version": 1, "createdAt": null, "updatedAt": "2026-05-16T22:41:52.482355", "level": 3, "castingTime": "Действие", "range": "150 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 4-го уровня или выше, урон увеличивается на 1к6 за каждый уровень ячейки выше третьего.", "requiresSavingThrow": null, "requiresAttackRoll": null, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": "крошечный шарик из гуано летучей мыши и серы", "materialCost": null, "materialConsumed": false, "isHealing": null, "healingDice": null, "requiresLineOfSight": null, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": true, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": null, "damageType": null, "targetType": null, "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "fireball", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": [24, 26, 30]}, {"id": 365, "name": "Молния", "description": "Разряд молнии формирует линию длиной 100 футов и шириной 5 футов, вылетающую в выбранном вами направлении. Все существа в линии должны совершить спасбросок Ловкости. Существо получает 8к6 урона электричеством при провале или половину урона при успехе.\\nМолния поджигает горючие предметы в поражаемой области, которые никто не несёт и не носит.", "source": "PHB 2014", "version": 1, "createdAt": null, "updatedAt": "2026-05-16T22:41:52.482355", "level": 3, "castingTime": "Действие", "range": "На себя (100-футовая линия)", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 4-го уровня или выше, урон увеличивается на 1к6 за каждый уровень ячейки выше третьего.", "requiresSavingThrow": null, "requiresAttackRoll": null, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": "кусочек меха и жезл из янтаря, кристалла или стекла", "materialCost": null, "materialConsumed": false, "isHealing": null, "healingDice": null, "requiresLineOfSight": null, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": true, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": null, "damageType": null, "targetType": null, "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "lightning_bolt", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": [16]}, {"id": 260, "name": "Град", "description": "На землю в цилиндре с радиусом 20 футов и высотой 40 футов с центром на точке в пределах дистанции падают куски льда. Все существа в цилиндре должны совершить спасбросок Ловкости. Существо получает 2к8 дробящего урона и 4к6 урона холодом при провале или половину этого урона при успехе.\\nГрад превращает область воздействия в\\nтруднопроходимую местность\\nдо конца вашего следующего хода.", "source": "PHB 2014", "version": 1, "createdAt": null, "updatedAt": "2026-05-16T22:41:52.482355", "level": 4, "castingTime": "Действие", "range": "300 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 5-го уровня или выше, дробящий урон увеличивается на 1к8 за каждый уровень ячейки выше четвертого.", "requiresSavingThrow": null, "requiresAttackRoll": null, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": "щепотка пыли и несколько капель воды", "materialCost": null, "materialConsumed": false, "isHealing": null, "healingDice": null, "requiresLineOfSight": null, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": true, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": null, "damageType": null, "targetType": null, "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "ice_storm", "damageParts": null, "shortDescription": null, "availableForClassIds": [4, 10, 12], "availableForSubclassIds": [16, 18, 32]}, {"id": 373, "name": "Небесный огонь", "description": "В указанном вами месте возникает вертикальная колонна божественного пламени. Все существа в цилиндре с радиусом 10 футов и высотой 40 футов с центром на точке в пределах дистанции должны совершить спасбросок Ловкости. При провале существо получает 4к6 урона излучением и 4к6 урона огнём, а при успехе половину этого урона.", "source": "PHB 2014", "version": 1, "createdAt": null, "updatedAt": "2026-05-16T22:41:52.482355", "level": 5, "castingTime": "Действие", "range": "60 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 6-го уровня или выше, урон излучением или урон огнём (на ваш выбор) увеличивается на 1к6 за каждый уровень ячейки выше пятого.", "requiresSavingThrow": null, "requiresAttackRoll": null, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": "щепотка серы", "materialCost": null, "materialConsumed": false, "isHealing": null, "healingDice": null, "requiresLineOfSight": null, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": true, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": null, "damageType": null, "targetType": null, "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "flame_strike", "damageParts": null, "shortDescription": null, "availableForClassIds": [3], "availableForSubclassIds": [19, 24, 26, 31]}, {"id": 48, "name": "Лечение ран", "description": "Существо, которого вы касаетесь, восстанавливает количество хитов, равное 1к8 + ваш модификатор базовой характеристики. Это заклинание не оказывает никакого эффекта на Нежить и Конструктов.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T22:37:10.895311", "updatedAt": "2026-05-16T22:41:52.482355", "level": 1, "castingTime": "Действие", "range": "Касание", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 2-го уровня или выше, лечение увеличивается на 1к8 за каждый уровень ячейки выше первого.", "requiresSavingThrow": false, "requiresAttackRoll": false, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": true, "healingDice": "1d8", "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": "none", "damageType": null, "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "cure_wounds", "damageParts": null, "shortDescription": null, "availableForClassIds": [2, 3, 4, 7, 8], "availableForSubclassIds": []}, {"id": 47, "name": "Лечащее слово", "description": "Существо на ваш выбор, видимое в пределах дистанции, восстанавливает количество хитов, равное 1к4 + ваш модификатор базовой характеристики. Это заклинание не оказывает никакого эффекта на Нежить и Конструктов.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T22:37:10.895311", "updatedAt": "2026-05-16T22:41:52.482355", "level": 1, "castingTime": "Бонусное действие", "range": "60 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 2-го уровня или выше, количество восстанавливаемых хитов увеличивается на 1к4 за каждый уровень ячейки выше первого.", "requiresSavingThrow": false, "requiresAttackRoll": false, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": true, "healingDice": "1d4", "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": false, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": "none", "damageType": null, "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "healing_word", "damageParts": null, "shortDescription": null, "availableForClassIds": [2, 3, 4], "availableForSubclassIds": []}, {"id": 12, "name": "Мистический заряд", "description": "К существу, находящемуся в пределах дистанции, устремляется луч потрескивающей энергии. Совершите дальнобойную атаку заклинанием по цели. При попадании цель получает урон силовым полем 1к10.\\nЗаклинание создаёт ещё один луч, когда вы достигаете больших уровней: два луча на 5-м уровне, три луча на 11-м уровне и четыре луча на 17-м уровне.\\nВы можете направить лучи в одну цель или в разные. Для каждого луча совершите свой бросок атаки.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T17:22:16.90104", "updatedAt": "2026-05-16T22:41:52.482355", "level": 0, "castingTime": "Действие", "range": "120 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": null, "requiresSavingThrow": false, "requiresAttackRoll": true, "damageDice": "1d10", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": "rangedSpell", "damageType": "force", "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "eldritch_blast", "damageParts": null, "shortDescription": null, "availableForClassIds": [11], "availableForSubclassIds": []}, {"id": 111, "name": "Палящий луч", "description": "Вы создаете три огненных луча и направляете их на цели, находящиеся в пределах дистанции. Это может быть одна цель или несколько.\\nДля каждого луча совершите дальнобойную атаку заклинанием. При попадании цель получает 2к6 урона огнём.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T23:36:57.058586", "updatedAt": "2026-05-16T22:41:52.482355", "level": 2, "castingTime": "Действие", "range": "120 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 3-го уровня или выше, вы создаете один дополнительный луч за каждый уровень ячейки выше второго.", "requiresSavingThrow": false, "requiresAttackRoll": true, "damageDice": "2d6", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": "none", "attackType": "rangedSpell", "damageType": "fire", "targetType": "multipleCreatures", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "scorching_ray", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": [26]}, {"id": 35, "name": "Волшебная стрела", "description": "Вы создаете три светящихся дротика из магической силы. Каждый дротик попадает в существо на ваш выбор, видимое в пределах дистанции. Каждый дротик причиняет 1к4 + 1 урона силовым полем. Все дротики поражают одновременно, и вы можете направить их как в одно существо, так и в разных.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T21:48:35.40584", "updatedAt": "2026-05-16T22:41:52.482355", "level": 1, "castingTime": "Действие", "range": "120 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 2-го уровня или выше, заклинание создает по одному дополнительному дротику за каждый уровень ячейки выше первого.", "requiresSavingThrow": false, "requiresAttackRoll": false, "damageDice": "1d4+1", "damageScaling": null, "conditions": null, "materialDescription": null, "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": false, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": "none", "damageType": "force", "targetType": "multipleCreatures", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "magic_missile", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": []}, {"id": 258, "name": "Голод Хадара", "description": "Вы открываете врата в межзвёздную тьму, область, населённую неизвестными кошмарами. Появляется сфера черноты и холода с радиусом 20 футов с центром на точке в пределах дистанции, существующая, пока активно заклинание. Эта пустота заполнена какофонией тихих шёпотов и хлюпающих шумов, которые слышно в пределах 30 футов. Никакой свет, ни магический, ни обычный, не может осветить эту местность, и существа, полностью находящиеся в этой области,\\nослеплены\\n.\\nПустота создаёт искажения в ткани пространства, и её местность является\\nтруднопроходимой\\n. Все существа, начинающие ход в этой местности, получают 2к6 урона холодом. Все существа, оканчивающие ход в этой местности, должны преуспеть в спасброске Ловкости, иначе получают 2к6 урона кислотой, так как к ним прикасаются бледные потусторонние щупальца.", "source": "PHB 2014", "version": 1, "createdAt": null, "updatedAt": "2026-05-16T22:41:52.482355", "level": 3, "castingTime": "Действие", "range": "150 футов", "duration": "1 минута", "concentration": true, "ritual": false, "higherLevel": null, "requiresSavingThrow": null, "requiresAttackRoll": null, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": "маринованное щупальце осьминога", "materialCost": null, "materialConsumed": false, "isHealing": null, "healingDice": null, "requiresLineOfSight": null, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": true, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "conjuration", "savingThrowAbility": null, "attackType": null, "damageType": null, "targetType": null, "areaOfEffectType": null, "durationType": "timed", "referenceKey": "hunger_of_hadar", "damageParts": null, "shortDescription": null, "availableForClassIds": [11], "availableForSubclassIds": []}, {"id": 73, "name": "Цветной шарик", "description": "Вы бросаете\\n4-дюймовую\\nсферу энергии в существо, которое видите в пределах дистанции. Выберите звук, кислоту, огонь, холод, электричество или яд при создании сферы, а затем совершите по цели дальнобойную атаку заклинанием. Если атака попадает, существо получает 3к8 урона выбранного вида.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T22:37:10.895311", "updatedAt": "2026-05-16T22:41:52.482355", "level": 1, "castingTime": "Действие", "range": "90 футов", "duration": "Мгновенная", "concentration": false, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 2-го уровня или выше, урон увеличивается на 1к8 за каждый уровень ячейки выше первого.", "requiresSavingThrow": false, "requiresAttackRoll": true, "damageDice": "3d8", "damageScaling": null, "conditions": null, "materialDescription": "алмаз, стоящий как минимум 50 зм", "materialCost": 50, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": true, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "evocation", "savingThrowAbility": null, "attackType": "rangedSpell", "damageType": null, "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "instantaneous", "referenceKey": "chromatic_orb", "damageParts": null, "shortDescription": null, "availableForClassIds": [10, 12], "availableForSubclassIds": []}, {"id": 132, "name": "Удержание личности", "description": "Выберите Гуманоида, которого видите в пределах дистанции. Цель должна преуспеть в спасброске Мудрости, иначе станет\\nпарализованной\\nна время действия заклинания. В конце каждого своего хода цель может совершать новые спасброски Мудрости. При успехе заклинание на этой цели оканчивается.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-30T01:18:10.66791", "updatedAt": "2026-05-16T22:41:52.482355", "level": 2, "castingTime": "Действие", "range": "60 футов", "duration": "1 минута", "concentration": true, "ritual": false, "higherLevel": "Если вы накладываете это заклинание, используя ячейку 3-го уровня или выше, вы можете сделать целью одно дополнительное существо за каждый уровень ячейки выше 2-го. Эти Гуманоиды должны находиться в пределах 30 футов друг от друга, когда вы нацеливаетесь на них.", "requiresSavingThrow": true, "requiresAttackRoll": false, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": "небольшой прямой кусочек железа", "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": true, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "enchantment", "savingThrowAbility": "wisdom", "attackType": "none", "damageType": null, "targetType": "singleCreature", "areaOfEffectType": null, "durationType": "timed", "referenceKey": "hold_person", "damageParts": null, "shortDescription": null, "availableForClassIds": [2, 3, 4, 10, 11, 12], "availableForSubclassIds": [30, 33]}, {"id": 55, "name": "Невидимый слуга", "description": "Это заклинание создает\\nневидимую\\n, бессознательную и бесформенную силу Среднего размера, выполняющую отдаваемые вами простые поручения. Слуга появляется в свободном пространстве на земле в пределах дистанции. У него КД 10, 1 хит, Сила 2, и он не может атаковать. Если его хиты опускаются до 0, заклинание оканчивается.\\nОдин раз в каждом своем ходу вы можете бонусным действием отдать команду слуге переместиться на 15 футов и совершить манипуляции с каким-нибудь предметом. Слуга может выполнять простые задачи, доступные человеку, такие как подношение предметов, чистка, починка и складывание одежды, разжигание костра, подача пищи и разливание вина. Получив команду, слуга начинает её выполнять, стараясь изо всех сил, пока не выполнит, после чего начинает ждать вашу следующую команду.\\nЕсли вы отдаёте слуге поручение, из-за которого тот окажется дальше чем в 60 футах от вас, заклинание оканчивается.", "source": "PHB 2014", "version": 1, "createdAt": "2026-03-29T22:37:10.895311", "updatedAt": "2026-05-16T22:41:52.482355", "level": 1, "castingTime": "Действие", "range": "60 футов", "duration": "1 час", "concentration": false, "ritual": true, "higherLevel": null, "requiresSavingThrow": false, "requiresAttackRoll": false, "damageDice": null, "damageScaling": null, "conditions": null, "materialDescription": "часть тетивы и кусочек дерева", "materialCost": null, "materialConsumed": false, "isHealing": false, "healingDice": null, "requiresLineOfSight": true, "requiresVerbal": true, "requiresSomatic": true, "requiresMaterial": true, "areaOfEffectSize": null, "areaOfEffectSecondarySize": null, "areaOfEffectHeight": null, "schoolValue": "conjuration", "savingThrowAbility": null, "attackType": "none", "damageType": null, "targetType": null, "areaOfEffectType": null, "durationType": "timed", "referenceKey": "unseen_servant", "damageParts": null, "shortDescription": null, "availableForClassIds": [2, 11, 12], "availableForSubclassIds": []}]$baseline$::jsonb)
  LOOP
    SELECT to_jsonb(s) - 'healingScaling' - 'healingAddsCastingModifier'
      INTO actual FROM spell_data s WHERE "referenceKey" = expected->>'referenceKey';
    IF actual IS DISTINCT FROM expected THEN
      RAISE EXCEPTION 'Spell pilot preflight mismatch for %: expected original catalog row', expected->>'referenceKey';
    END IF;
    IF EXISTS (SELECT 1 FROM spell_data WHERE "referenceKey" = expected->>'referenceKey'
        AND ("healingScaling" IS NOT NULL OR "healingAddsCastingModifier" IS NOT NULL)) THEN
      RAISE EXCEPTION 'Spell pilot would overwrite existing healing data for %', expected->>'referenceKey';
    END IF;
  END LOOP;
  UPDATE spell_data SET "damageScaling" = '{"mode": "casterLevel", "scalingByCasterLevel": [{"k": 1, "v": "1d6"}, {"k": 5, "v": "2d6"}, {"k": 11, "v": "3d6"}, {"k": 17, "v": "4d6"}]}'::json, "requiresSavingThrow" = TRUE, "savingThrowAbility" = 'dexterity' WHERE "referenceKey" = 'acid_splash';
  UPDATE spell_data SET "damageScaling" = '{"mode": "casterLevel", "scalingByCasterLevel": [{"k": 1, "v": "1d10"}, {"k": 5, "v": "2d10"}, {"k": 11, "v": "3d10"}, {"k": 17, "v": "4d10"}]}'::json WHERE "referenceKey" = 'fire_bolt';
  UPDATE spell_data SET "damageScaling" = '{"mode": "casterLevel", "scalingByCasterLevel": [{"k": 1, "v": "1d8"}, {"k": 5, "v": "2d8"}, {"k": 11, "v": "3d8"}, {"k": 17, "v": "4d8"}]}'::json WHERE "referenceKey" = 'ray_of_frost';
  UPDATE spell_data SET "damageScaling" = '{"mode": "casterLevel", "scalingByCasterLevel": [{"k": 1, "v": "1d8"}, {"k": 5, "v": "2d8"}, {"k": 11, "v": "3d8"}, {"k": 17, "v": "4d8"}]}'::json WHERE "referenceKey" = 'sacred_flame';
  UPDATE spell_data SET "damageScaling" = '{"mode": "casterLevel", "scalingByCasterLevel": [{"k": 1, "v": "1d4"}, {"k": 5, "v": "2d4"}, {"k": 11, "v": "3d4"}, {"k": 17, "v": "4d4"}]}'::json WHERE "referenceKey" = 'vicious_mockery';
  UPDATE spell_data SET "damageScaling" = '{"mode": "slotLevel", "scalingBySlotLevel": [{"k": 1, "v": "3d6"}, {"k": 2, "v": "4d6"}, {"k": 3, "v": "5d6"}, {"k": 4, "v": "6d6"}, {"k": 5, "v": "7d6"}, {"k": 6, "v": "8d6"}, {"k": 7, "v": "9d6"}, {"k": 8, "v": "10d6"}, {"k": 9, "v": "11d6"}]}'::json WHERE "referenceKey" = 'burning_hands';
  UPDATE spell_data SET "damageScaling" = '{"mode": "slotLevel", "scalingBySlotLevel": [{"k": 1, "v": "2d8"}, {"k": 2, "v": "3d8"}, {"k": 3, "v": "4d8"}, {"k": 4, "v": "5d8"}, {"k": 5, "v": "6d8"}, {"k": 6, "v": "7d8"}, {"k": 7, "v": "8d8"}, {"k": 8, "v": "9d8"}, {"k": 9, "v": "10d8"}]}'::json WHERE "referenceKey" = 'thunderwave';
  UPDATE spell_data SET "damageDice" = '8d6', "damageType" = 'fire', "damageScaling" = '{"mode": "slotLevel", "scalingBySlotLevel": [{"k": 3, "v": "8d6"}, {"k": 4, "v": "9d6"}, {"k": 5, "v": "10d6"}, {"k": 6, "v": "11d6"}, {"k": 7, "v": "12d6"}, {"k": 8, "v": "13d6"}, {"k": 9, "v": "14d6"}]}'::json, "requiresSavingThrow" = TRUE, "savingThrowAbility" = 'dexterity', "requiresAttackRoll" = FALSE, "attackType" = 'none', "targetType" = 'area', "areaOfEffectType" = 'sphere', "areaOfEffectSize" = 20 WHERE "referenceKey" = 'fireball';
  UPDATE spell_data SET "damageDice" = '8d6', "damageType" = 'lightning', "damageScaling" = '{"mode": "slotLevel", "scalingBySlotLevel": [{"k": 3, "v": "8d6"}, {"k": 4, "v": "9d6"}, {"k": 5, "v": "10d6"}, {"k": 6, "v": "11d6"}, {"k": 7, "v": "12d6"}, {"k": 8, "v": "13d6"}, {"k": 9, "v": "14d6"}]}'::json, "requiresSavingThrow" = TRUE, "savingThrowAbility" = 'dexterity', "requiresAttackRoll" = FALSE, "attackType" = 'none', "targetType" = 'area', "areaOfEffectType" = 'line', "areaOfEffectSize" = 100, "areaOfEffectSecondarySize" = 5 WHERE "referenceKey" = 'lightning_bolt';
